"""Builds the generated files from their sources.

Sources: app/data/library.js, prompt/daily-brief-prompt.md,
prompt/daily-brief-prompt-compact.md, examples/sample-brief.json and
examples/sample-settings.json. Generated: the library list inside the full
prompt, prompt/category-library.md, app/data/prompts.js and app/data/sample.js
(the app cannot read loose files when it is opened straight from disk).

    python -m dailybrief build-assets          # rewrite generated files
    python -m dailybrief build-assets --check  # fail if any is out of date
"""
from __future__ import annotations

import json
from pathlib import Path

from .jsdata import library, write_js_json
from .paths import APP_DIR, EXAMPLES_DIR, PROMPT_DIR
from .store import write_text

LIB_BEGIN = "<!-- LIBRARY:BEGIN -->"
LIB_END = "<!-- LIBRARY:END -->"
HEADER = ("/* Generated by `python -m dailybrief build-assets`. Do not edit by hand;\n"
          "   edit the source named in dailybrief/assets.py and rebuild. */")


def library_list(lib: dict) -> str:
    lines = ["Starter packs:", ""]
    for i, p in enumerate(lib["packs"], 1):
        lines.append(f"- P{i}. **{p['name']}**: {p['description']} ({', '.join(p['categories'])})")
    lines += ["", "Categories:", ""]
    n = 0
    for g in lib["groups"]:
        lines.append(f"*{g['name']}*")
        lines.append("")
        for c in lib["categories"]:
            if c["group"] != g["id"]:
                continue
            n += 1
            lines.append(f"{n}. `{c['id']}` **{c['name']}**: {c['description']}")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def library_markdown(lib: dict) -> str:
    out = ["# Daily Brief category library", "",
           "Upload this file next to the prompt so the assistant can offer these categories.",
           "Generated from app/data/library.js.", "", library_list(lib), "## Details", ""]
    for c in lib["categories"]:
        out.append(f"### {c['name']} (`{c['id']}`)")
        out.append("")
        out.append(c["description"])
        out.append("")
        out.append("- Queries: " + " / ".join(f"`{q}`" for q in c["queries"]))
        for i, g in enumerate(c["require"], 1):
            out.append(f"- Must mention one of (group {i}): " + ", ".join(g))
        if c["exclude"]:
            out.append("- Leave out: " + ", ".join(c["exclude"]))
        if c.get("feeds"):
            out.append("- Publisher feeds: " + ", ".join(c["feeds"]))
        if c.get("topic_feeds"):
            out.append("- On-topic feeds (no must-mention term needed): " + ", ".join(c["topic_feeds"]))
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def _with_library(prompt: str, lib: dict) -> str:
    i = prompt.find(LIB_BEGIN)
    j = prompt.find(LIB_END)
    if i < 0 or j < i:
        raise ValueError("daily-brief-prompt.md has no library markers")
    return prompt[:i + len(LIB_BEGIN)] + "\n" + library_list(lib) + prompt[j:]


def build(check: bool = False) -> list:
    """Returns the list of files that changed (or would change with check=True)."""
    lib = library()
    changed = []

    def put(path: Path, text: str) -> None:
        old = path.read_text(encoding="utf-8") if path.exists() else None
        if old != text:
            changed.append(str(path))
            if not check:
                write_text(path, text)

    full_path = PROMPT_DIR / "daily-brief-prompt.md"
    full = _with_library(full_path.read_text(encoding="utf-8"), lib)
    put(full_path, full)
    compact = (PROMPT_DIR / "daily-brief-prompt-compact.md").read_text(encoding="utf-8")
    lib_md = library_markdown(lib)
    put(PROMPT_DIR / "category-library.md", lib_md)
    prompts = {"full": full, "compact": compact, "library": lib_md}
    put(APP_DIR / "data" / "prompts.js", HEADER + "\nwindow.DB_PROMPTS = " + json.dumps(prompts, indent=1, ensure_ascii=True) + ";\n")
    sample = {"brief": json.loads((EXAMPLES_DIR / "sample-brief.json").read_text(encoding="utf-8")),
              "settings": json.loads((EXAMPLES_DIR / "sample-settings.json").read_text(encoding="utf-8"))}
    put(APP_DIR / "data" / "sample.js", HEADER + "\nwindow.DB_SAMPLE = " + json.dumps(sample, indent=1, ensure_ascii=True) + ";\n")
    return changed


__all__ = ["build", "library_list", "library_markdown", "write_js_json"]
